on conflict (grade, num) do update set question = excluded.question, options = excluded.options, correct = excluded.correct;

-- 10-sinf: 40 ta savol
on conflict (grade, num) do update set question = excluded.question, options = excluded.options, correct = excluded.correct;

-- 11-sinf: 40 ta savol
on conflict (grade, num) do update set question = excluded.question, options = excluded.options, correct = excluded.correct;

-- O'QITUVCHI

-- O'QUVCHILAR
